GUARDS = r"""
CREATE FUNCTION guard_exam_grading_workspace() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'exam_workspace_immutable' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM exam_parsing_jobs j JOIN exam_submission_links k ON k.job_id=j.id
 JOIN paper_question_mappings m ON m.id=NEW.paper_question_mapping_id
 JOIN answer_alignment_artifacts al ON al.id=NEW.alignment_artifact_id
 WHERE j.id=NEW.parsing_job_id AND j.status='succeeded' AND m.paper_version_id=k.paper_version_id
 AND m.legacy_question_id=NEW.question_id AND al.submission_id=k.submission_id
 AND al.canonical_artifact_id=j.canonical_artifact_id AND
al.assignment_id=m.canonical_assignment_id)
 THEN RAISE EXCEPTION 'exam_workspace_source_mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION guard_exam_scoring_job() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'exam_score_history_immutable' USING ERRCODE='23514';
END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'pending' THEN RAISE EXCEPTION 'exam_score_initial_state' USING
ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM exam_grading_workspaces w JOIN exam_submission_links k ON
k.job_id=w.parsing_job_id
   JOIN grade_input_artifacts gi ON gi.id=NEW.grade_input_id JOIN answer_review_decisions ar ON
ar.id=NEW.answer_review_id
   WHERE w.id=NEW.workspace_id AND gi.submission_id=k.submission_id AND gi.question_id=w.question_id
   AND gi.review_decision_id=ar.id AND gi.alignment_artifact_id=w.alignment_artifact_id AND
ar.submission_id=k.submission_id AND ar.question_id=w.question_id)
  THEN RAISE EXCEPTION 'exam_score_input_mismatch' USING ERRCODE='23514'; END IF;
 ELSE
  IF OLD.status IN ('succeeded','failed','invalidated') OR NEW.id<>OLD.id OR
NEW.workspace_id<>OLD.workspace_id
   OR NEW.answer_review_id<>OLD.answer_review_id OR NEW.grade_input_id<>OLD.grade_input_id
   OR NEW.requested_by_user_id<>OLD.requested_by_user_id OR NEW.created_at<>OLD.created_at
  THEN RAISE EXCEPTION 'exam_score_identity_immutable' USING ERRCODE='23514'; END IF;
  IF NEW.status='running' AND OLD.status='running' AND (OLD.lease_token IS DISTINCT FROM
NEW.lease_token OR OLD.lease_expires_at<=clock_timestamp())
  THEN RAISE EXCEPTION 'exam_score_lease_lost' USING ERRCODE='23514'; END IF;
  IF NEW.status='succeeded' AND (OLD.status<>'running' OR OLD.lease_expires_at<=clock_timestamp())
  THEN RAISE EXCEPTION 'exam_score_lease_lost' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status='succeeded' AND NOT EXISTS(SELECT 1 FROM grade_proposal_artifacts gp JOIN
grade_input_artifacts gi ON gi.id=NEW.grade_input_id
  WHERE gp.id=NEW.proposal_id AND gp.grade_input_artifact_id=gi.id AND
gp.grade_input_sha256=gi.input_sha256
  AND gp.submission_id=gi.submission_id AND gp.question_id=gi.question_id)
 THEN RAISE EXCEPTION 'exam_score_result_mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;"""

ACTIONS = ["exam.mark.read", "exam.answer.review", "exam.score.request", "exam.score.review"]
