def install_security():
    for statement in GUARDS.strip().split(";\nCREATE FUNCTION"):
        op.execute(
            statement if statement.startswith("CREATE FUNCTION") else "CREATE FUNCTION" + statement
        )
    for table, function, events in [
        ("exam_grading_workspaces", "guard_exam_grading_workspace", "INSERT OR UPDATE OR DELETE"),
        ("exam_scoring_jobs", "guard_exam_scoring_job", "INSERT OR UPDATE OR DELETE"),
        ("exam_grading_operations", "guard_security_immutable", "UPDATE OR DELETE"),
    ]:
        op.execute(
            f"CREATE TRIGGER protect_exam_mark BEFORE {events} ON {table} FOR "
            f"EACH ROW EXECUTE FUNCTION {function}()"
        )
    db = op.get_bind()
    for code in ACTIONS:
        db.execute(
            sa.text(
                "INSERT INTO permission_definitions VALUES "
                "(:code,true,ARRAY['installation','exam_event','exam_session'])"
            ),
            dict(code=code),
        )
    for i, rid in enumerate(ROLES):
        db.execute(
            sa.text("INSERT INTO security_role_versions VALUES (CAST(:id AS uuid),:name,1,NULL)"),
            dict(id=rid, name="exam_mark_deployer" if i else "exam_mark_operator"),
        )
        codes = (
            list(
                db.execute(
                    sa.text(
                        "SELECT permission_code FROM security_role_permissions "
                        "WHERE role_version_id='11111111-b14b-4000-8000-000000000001'"
                    )
                ).scalars()
            )
            + ACTIONS
            + (["security.grants.manage"] if i else [])
        )
        for code in codes:
            db.execute(
                sa.text("INSERT INTO security_role_permissions VALUES (CAST(:id AS uuid),:code)"),
                dict(id=rid, code=code),
            )
        db.execute(
            sa.text(
                "UPDATE security_role_versions SET sealed_at=clock_timestamp() "
                "WHERE id=CAST(:id AS uuid)"
            ),
            dict(id=rid),
        )


def remove_security():
    op.execute(
        "LOCK TABLE "
        "exam_grading_workspaces,exam_scoring_jobs,exam_grading_operations,"
        "security_grants IN ACCESS EXCLUSIVE MODE"
    )
    db = op.get_bind()
    for table in ["exam_grading_workspaces", "exam_scoring_jobs", "exam_grading_operations"]:
        if db.scalar(sa.text(f"SELECT EXISTS(SELECT 1 FROM {table})")):
            raise RuntimeError("exam_mark_downgrade_requires_archived_data")
    if db.scalar(
        sa.text(
            "SELECT EXISTS(SELECT 1 FROM security_grants WHERE "
            "role_version_id=ANY(CAST(:ids AS uuid[])))"
        ),
        dict(ids=ROLES),
    ):
        raise RuntimeError("exam_mark_downgrade_requires_archived_grants")
    for table in ["exam_grading_workspaces", "exam_scoring_jobs", "exam_grading_operations"]:
        op.execute(f"DROP TRIGGER protect_exam_mark ON {table}")
    op.execute("DROP FUNCTION guard_exam_grading_workspace()")
    op.execute("DROP FUNCTION guard_exam_scoring_job()")
    op.execute(
        "ALTER TABLE security_role_permissions DISABLE TRIGGER immutable_security_role_permissions"
    )
    op.execute("ALTER TABLE security_role_versions DISABLE TRIGGER immutable_security_role")
    for rid in ROLES:
        db.execute(
            sa.text(
                "DELETE FROM security_role_permissions WHERE role_version_id=CAST(:id AS uuid)"
            ),
            dict(id=rid),
        )
        db.execute(
            sa.text("DELETE FROM security_role_versions WHERE id=CAST(:id AS uuid)"), dict(id=rid)
        )
    op.execute(
        "ALTER TABLE security_role_permissions ENABLE TRIGGER immutable_security_role_permissions"
    )
    op.execute("ALTER TABLE security_role_versions ENABLE TRIGGER immutable_security_role")
